const state={role:localStorage.getItem('spaflow-role')||'admin',branch:localStorage.getItem('spaflow-branch')||'SpaFlow Quận 1',view:'dashboard',classes:[{id:'SPA-K12',name:'Chăm sóc da chuyên sâu K12',teacher:'Nguyễn Thu Hà',branch:'SpaFlow Quận 1',schedule:'T2-T6 (08:30)',students:18,status:'Đang học'},{id:'SPA-K13',name:'Massage trị liệu K13',teacher:'Phạm Minh Thu',branch:'SpaFlow Quận 7',schedule:'T3-T5 (13:30)',students:12,status:'Sắp khai giảng'},{id:'SPA-K14',name:'Kỹ thuật viên Spa K14',teacher:'Trần Hải Yến',branch:'SpaFlow Thủ Đức',schedule:'T2-T4 (08:00)',students:20,status:'Chuẩn bị'}],students:[{id:'HV001245',name:'Nguyễn Thị Mai',phone:'0903 456 789',attendance:'11/12',rate:'91.7%',status:'Đang học'},{id:'HV001246',name:'Trần Minh Thư',phone:'0987 654 321',attendance:'10/12',rate:'83.3%',status:'Đang học'},{id:'HV001247',name:'Lê Hoàng Yến',phone:'0912 345 678',attendance:'12/12',rate:'100%',status:'Đang học'},{id:'HV001248',name:'Phạm Thu Trang',phone:'0938 765 432',attendance:'9/12',rate:'75%',status:'Đang học'}],attendance:JSON.parse(localStorage.getItem('spaflow-attendance')||'[]')};
let apiToken=sessionStorage.getItem('spaflow-token')||'';
async function api(path,options={}){let headers={'Content-Type':'application/json',...(options.headers||{})};if(apiToken)headers.Authorization='Bearer '+apiToken;let r=await fetch('/api/'+path,{...options,headers});let data=await r.json();if(!r.ok)throw new Error(data.error||'Không thể kết nối máy chủ');return data}
const roles={admin:{name:'Admin',caption:'Quản trị hệ thống',menu:[['⌂','Tổng quan','dashboard'],['⌂','Chi nhánh','branches'],['♧','Nhân sự & phân quyền','staff'],['♙','Khách hàng (CRM)','customers'],['▣','Lịch hẹn','appointments'],['♧','Dịch vụ & sản phẩm','services'],['▣','Kho & tồn kho','inventory'],['◴','Thu chi & doanh thu','finance'],['♢','Đào tạo','classes'],['♙','Học viên','students'],['⌖','Điểm danh','attendance'],['▥','Báo cáo','reports'],['⚙','Cài đặt','settings']]},cskh:{name:'CSKH',caption:'Chăm sóc khách hàng',menu:[['⌂','Tổng quan','dashboard'],['♙','Khách hàng','customers'],['◌','Tư vấn & Lead','leads'],['▣','Lịch hẹn','appointments'],['♡','Chăm sóc sau điều trị','aftercare'],['◴','Tin nhắn','messages'],['▥','Báo cáo CSKH','reports']]},manager:{name:'Quản lý chi nhánh',caption:'SpaFlow Quận 1',menu:[['⌂','Tổng quan','dashboard'],['▣','Lịch hẹn','appointments'],['♙','Khách hàng','customers'],['♧','Nhân viên','staff'],['□','Phòng dịch vụ','rooms'],['▣','Sản phẩm & kho','inventory'],['◴','Thu chi','finance'],['♢','Lớp học & đào tạo','classes'],['⌖','Điểm danh','attendance'],['▥','Báo cáo','reports']]},student:{name:'Nguyễn Thị Mai',caption:'Học viên',menu:[['⌂','Trang chủ','dashboard'],['♢','Khóa học của tôi','classes'],['▣','Lịch học','schedule'],['⌖','Điểm danh','attendance'],['▥','Kết quả học tập','results'],['▤','Học phí','tuition'],['□','Tài liệu học tập','materials'],['♧','Hồ sơ cá nhân','profile']]}};
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('vi-VN').format(n)+' đ';
let drawerFocus=null;
function drawerIsMobile(){return window.matchMedia('(max-width: 780px)').matches}
function setDrawer(open){let sidebar=$('#sidebar'),overlay=$('#drawerOverlay'),trigger=$('#mobileMenu');let next=Boolean(open)&&drawerIsMobile();if(next&&!sidebar.classList.contains('open'))drawerFocus=document.activeElement;sidebar.classList.toggle('open',next);overlay.classList.toggle('open',next);document.body.classList.toggle('drawer-open',next);trigger.setAttribute('aria-expanded',String(next));if(next)setTimeout(()=>$('#drawerClose').focus(),20);else if(drawerFocus&&typeof drawerFocus.focus==='function')drawerFocus.focus();}
function init(){renderShell();renderPage();$('#mobileMenu').onclick=()=>setDrawer(!$('#sidebar').classList.contains('open'));$('#drawerClose').onclick=()=>setDrawer(false);$('#drawerOverlay').onclick=()=>setDrawer(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modalRoot').children.length)closeModal();else setDrawer(false)}});window.addEventListener('resize',()=>{if(!drawerIsMobile())setDrawer(false)});$('#roleButton').onclick=rolePicker;$('#branchButton').onclick=branchPicker;$('#guide').onclick=guide;$('#globalSearch').oninput=e=>{if(e.target.value.length>2){state.view='customers';renderPage(e.target.value)}}}
function renderShell(){let r=roles[state.role];$('#roleName').textContent=r.name;$('#roleCaption').textContent=r.caption;$('#profileRole').textContent=r.caption;$('#branchName').textContent=state.branch;$('#greeting').innerHTML=`Xin chào, ${r.name}! <span>👋</span>`;$('#heroCopy').textContent=state.role==='student'?'Chào mừng bạn đến với hệ thống đào tạo SpaFlow.':'Tổng quan hoạt động của '+state.branch+' hôm nay';$('#nav').innerHTML=r.menu.map(x=>`<button class="${state.view===x[2]?'active':''}" data-view="${x[2]}"><span class="ico">${x[0]}</span>${x[1]}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;setDrawer(false);renderShell();renderPage()});let actions=state.role==='student'?[['⌖','Điểm danh'],['▤','Tài liệu'],['◉','Học online']]:[['▣','Tạo lịch hẹn'],['♙','Thêm khách hàng'],['♢','Tạo lớp học']];$('#quick').innerHTML=actions.map(a=>`<button onclick="quickAction('${a[1]}')">${a[0]}<span>${a[1]}</span></button>`).join('')}
function renderPage(query=''){let v=state.view;let generic=['branches','leads','aftercare','messages','rooms','schedule','results','tuition','materials','profile'];$('#page').innerHTML=v==='dashboard'?dashboard():v==='classes'?classesPage():v==='students'?studentsPage():v==='attendance'?attendancePage():v==='appointments'?appointmentsPage():v==='customers'?customersPage(query):v==='staff'?staffPage():v==='services'?servicesPage():v==='inventory'?inventoryPage():v==='finance'?financePage():v==='reports'?reportsPage():v==='settings'?settingsPage():genericPage(v);if(apiToken&&v==='dashboard')loadDashboard();if(apiToken&&v==='customers')loadCustomers(query);if(apiToken&&v==='appointments')loadAppointments();if(apiToken&&v==='staff')loadStaff();if(apiToken&&v==='services')loadServices();if(apiToken&&v==='inventory')loadProducts();if(apiToken&&v==='finance')loadInvoices();if(apiToken&&v==='reports')loadReports();if(apiToken&&v==='settings')loadSettings();if(apiToken&&generic.includes(v))loadModuleRecords(v)}
function dashboard(){let student=state.role==='student';return `<div class="kpis">${(student?[['♢','Khóa học đang học','2 khóa'],['▣','Buổi học sắp tới','1 buổi'],['▥','Tiến độ học tập','68%'],['▤','Học phí còn lại','4.500.000 đ']]:[['◴','Doanh thu hôm nay','42.500.000 đ'],['▣','Lịch hẹn hôm nay','28'],['♙','Khách hàng mới','16'],['♢','Học viên đang học','87'],['□','Tồn kho cảnh báo','4']]).map((k,i)=>`<article class="kpi"><div class="kico">${k[0]}</div><div>${k[1]}<b data-kpi="${['revenue','appointments','customers','students','stock'][i]||'stock'}">${k[2]}</b>${i<4?'<small>▲ +'+(8+i*4)+'% so với hôm qua</small>':''}</div></article>`).join('')}</div><section class="grid"><article class="card"><div class="card-head"><h2>▥ ${student?'Tiến độ học tập':'Doanh thu 7 ngày gần nhất'}</h2><span class="link">Xem chi tiết</span></div><p class="revenue">${student?'68%':'285.600.000 đ'}</p><p class="growth">▲ +15% so với kỳ trước</p><div class="chart">${[42,55,65,72,80,88,100].map((h,i)=>`<div style="height:${h}%" data-day="${['T2','T3','T4','T5','T6','T7','CN'][i]}"></div>`).join('')}</div></article><article class="card"><div class="card-head"><h2>▣ ${student?'Lịch học sắp tới':'Lịch hẹn hôm nay (28)'}</h2><span class="link">Xem tất cả</span></div>${appointments().slice(0,4).map(a=>appointmentHTML(a)).join('')}</article><article class="card"><div class="card-head"><h2>□ ${student?'Thông báo mới':'Cảnh báo tồn kho (4)'}</h2><span class="link">Xem tất cả</span></div>${(student?['Lịch học ngày 25/11 đã được cập nhật','Nhắc nhở: Đừng quên điểm danh','Tài liệu mới: Giáo trình chăm sóc da']:['Serum HA cấp ẩm (50ml)','Mặt nạ phục hồi da','Kem chống nắng SPF50','Tinh dầu massage']).map((x,i)=>`<div class="stock"><span class="product">${student?'●':'🧴'}</span><span>${x}</span><b>${student?'Hôm nay':'Còn '+(5+i)+' chai'}</b></div>`).join('')}</article><div class="bottom"><article class="card"><h2>⚡ Hoạt động gần đây</h2>${['Tạo lịch hẹn cho khách hàng Chị Ngọc Anh','Học viên Nguyễn Thị Mai đã check-in lớp K12','Nhập kho 20 sản phẩm Serum HA','Thanh toán hóa đơn HD2589'].map((x,i)=>`<div class="activity"><span>${['09:15','08:50','08:30','08:20'][i]}</span><span class="aicon">${['▣','⌖','□','◴'][i]}</span><span>${x}</span></div>`).join('')}</article><article class="card"><h2>⚡ Truy cập nhanh</h2><div class="action-grid"><button onclick="openClasses()">♢<br>Lớp học</button><button onclick="openAttendance()">⌖<br>Điểm danh</button><button onclick="setView('customers')">♙<br>Khách hàng</button><button onclick="setView('reports')">▥<br>Báo cáo</button></div></article></div><article class="card"><h2>⌂ Hiệu quả theo chi nhánh</h2><table class="branch-table"><tr><th>Chi nhánh</th><th>Doanh thu hôm nay</th><th>Lịch hẹn</th><th>Học viên</th></tr><tr><td>● SpaFlow Quận 1</td><td>18.500.000 đ</td><td>12</td><td>36</td></tr><tr><td>● SpaFlow Quận 7</td><td>14.800.000 đ</td><td>10</td><td>28</td></tr><tr><td>● SpaFlow Thủ Đức</td><td>9.200.000 đ</td><td>6</td><td>23</td></tr></table></article></section>`}
function appointments(){return [['09:00','Chị Ngọc Anh','Chăm sóc da chuyên sâu','Đã xác nhận'],['10:30','Chị Minh Thư','Massage thư giãn toàn thân','Đã xác nhận'],['13:30','Chị Lan Hương','Điều trị mụn chuyên sâu','Chờ xác nhận'],['15:00','Chị Thu Trang','Cấy collagen phục hồi da','Đã xác nhận']]};function appointmentHTML(a){return `<div class="appointment"><span class="time">${a[0]}</span><span class="face">👩🏻</span><span><b>${a[1]}</b><small>${a[2]}</small></span><span class="pill ${a[3].includes('Chờ')?'wait':''}">${a[3]}</span></div>`}
function classesPage(){return pageWrap('Quản lý lớp học','+ Tạo lớp học',`<div class="table-toolbar"><input placeholder="⌕  Tìm lớp học, mã lớp..."><select><option>Tất cả trạng thái</option><option>Đang học</option><option>Sắp khai giảng</option></select></div><table class="data-table"><thead><tr><th>Mã lớp</th><th>Tên lớp học</th><th>Giảng viên</th><th>Chi nhánh</th><th>Lịch học</th><th>Học viên</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${state.classes.map(c=>`<tr><td>${c.id}</td><td><b>${c.name}</b></td><td>${c.teacher}</td><td>${c.branch}</td><td>${c.schedule}</td><td>${c.students}</td><td><span class="status">${c.status}</span></td><td><button class="icon-btn" onclick="classDetail('${c.id}')">◉ Xem</button></td></tr>`).join('')}</tbody></table>`)}
function studentsPage(){return pageWrap('Danh sách học viên','+ Thêm học viên',studentTable())}function studentTable(){return `<div class="table-toolbar"><input placeholder="⌕  Tìm học viên, SĐT..."><select><option>Đang học</option><option>Tất cả</option></select></div><table class="data-table"><thead><tr><th>#</th><th>Học viên</th><th>Mã học viên</th><th>Điện thoại</th><th>Trạng thái</th><th>Điểm danh</th><th>Thao tác</th></tr></thead><tbody>${state.students.map((s,i)=>`<tr><td>${i+1}</td><td><span class="row-user"><span class="student-photo">👩🏻</span><b>${s.name}</b></span></td><td>${s.id}</td><td>${s.phone}</td><td><span class="status">${s.status}</span></td><td>${s.attendance} (${s.rate})</td><td><button class="icon-btn" onclick="studentDetail('${s.id}')">◉ Xem</button></td></tr>`).join('')}</tbody></table>`}
function attendancePage(){return pageWrap('Điểm danh học viên','⌖ Mở điểm danh',`<div class="card" style="margin:0"><div class="class-info"><span style="font-size:35px">♢</span><div><h3>Chăm sóc da chuyên sâu K12 — Buổi 12</h3><p>Hôm nay, 08:30 – 11:30 · SpaFlow Quận 1 · Phòng học A</p></div><button class="primary" style="margin-left:auto" onclick="openAttendance()">Điểm danh ngay</button></div>${attendanceTable()}</div>`)}
function attendanceTable(){let rows=state.attendance.length?state.attendance.concat([{date:'17/11/2026',time:'08:00',status:'Có mặt',gps:'SpaFlow Quận 1 (±10 m)'},{date:'14/11/2026',time:'08:02',status:'Có mặt',gps:'SpaFlow Quận 1 (±8 m)'},{date:'12/11/2026',time:'—',status:'Vắng',gps:'—'}]):[{date:'17/11/2026',time:'08:00',status:'Có mặt',gps:'SpaFlow Quận 1 (±10 m)'},{date:'14/11/2026',time:'08:02',status:'Có mặt',gps:'SpaFlow Quận 1 (±8 m)'},{date:'12/11/2026',time:'—',status:'Vắng',gps:'—'}];return `<table class="data-table"><thead><tr><th>Buổi học</th><th>Ngày học</th><th>Giờ check-in</th><th>Ảnh</th><th>Địa điểm GPS</th><th>Trạng thái</th></tr></thead><tbody>${rows.map((a,i)=>`<tr><td>Buổi ${12-i}</td><td>${a.date}</td><td>${a.time}</td><td>${a.image?'<img src="'+a.image+'" width="36" height="36" style="object-fit:cover;border-radius:6px">':'👩🏻'}</td><td>⌖ ${a.gps||'Đang xác minh'}</td><td><span class="status ${a.status==='Vắng'?'absent':''}">${a.status}</span></td></tr>`).join('')}</tbody></table>`}
function appointmentsPage(){return pageWrap('Lịch hẹn & đặt lịch','+ Đặt lịch',`<div id="appointmentRows" class="card" style="padding:0">${appointments().map(a=>appointmentHTML(a)).join('')}</div>`,'openAppointmentForm()')}
function customersPage(q=''){return pageWrap('Khách hàng CRM','+ Thêm khách hàng',`<div class="table-toolbar"><input id="customerSearch" value="${q}" placeholder="⌕  Tìm tên, số điện thoại..."><select><option>Tất cả trạng thái</option></select></div><table class="data-table"><thead><tr><th>Mã KH</th><th>Khách hàng</th><th>Số điện thoại</th><th>Nhóm</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="customerRows"><tr><td colspan="6">Đang tải dữ liệu...</td></tr></tbody></table>`,'openCustomerForm()')}
function servicesPage(){return pageWrap('Dịch vụ & bảng giá','+ Thêm dịch vụ',`<div class="table-toolbar"><input id="serviceSearch" placeholder="⌕ Tìm dịch vụ"><select id="serviceState"><option value="">Tất cả trạng thái</option><option value="1">Đang dùng</option><option value="0">Tạm dừng</option></select></div><table class="data-table"><thead><tr><th>Tên dịch vụ</th><th>Thời lượng</th><th>Giá bán</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="serviceRows"><tr><td colspan="5">Đang tải dữ liệu...</td></tr></tbody></table>`,'openServiceForm()')}
function inventoryPage(){return pageWrap('Sản phẩm & tồn kho','+ Thêm sản phẩm',`<div class="module-actions" style="padding:13px 15px"><button class="secondary" onclick="openStockForm()">⇅ Nhập / xuất kho</button><button class="secondary" onclick="loadProducts()">↻ Làm mới</button></div><table class="data-table"><thead><tr><th>SKU</th><th>Sản phẩm</th><th>Tồn kho</th><th>Ngưỡng cảnh báo</th><th>Giá bán</th><th>Thao tác</th></tr></thead><tbody id="productRows"><tr><td colspan="6">Đang tải dữ liệu...</td></tr></tbody></table>`,'openProductForm()')}
function financePage(){return `<div class="page-title"><h2>Thu chi & doanh thu</h2><button class="secondary" onclick="loadInvoices()">↻ Làm mới</button></div><section class="card table-card"><div class="table-toolbar"><input id="invoiceSearch" placeholder="⌕ Tìm mã hóa đơn, khách hàng..."><select id="invoiceState"><option value="">Tất cả trạng thái</option><option value="paid">Đã thanh toán</option><option value="partial">Còn công nợ</option><option value="unpaid">Chưa thanh toán</option></select></div><table class="data-table"><thead><tr><th>Mã hóa đơn</th><th>Khách hàng</th><th>Tổng tiền</th><th>Đã thu</th><th>Còn lại</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="invoiceRows"><tr><td colspan="7">Đang tải dữ liệu...</td></tr></tbody></table></section>`}
function reportsPage(){return `<div class="page-title"><h2>Báo cáo & thống kê</h2><button class="secondary" onclick="loadReports()">↻ Cập nhật</button></div><section id="reportRows" class="metric-grid"><div class="metric">Đang tải báo cáo...</div></section><section class="card" style="margin-top:14px"><h2>Tồn kho cần chú ý</h2><div id="lowStockRows">Đang tải dữ liệu...</div></section>`}
function settingsPage(){return `<div class="page-title"><h2>Cài đặt hệ thống</h2></div><section class="card"><form id="settingsForm" class="form-card"><label>Tên hệ thống<input name="spa_name" required></label><label>Số điện thoại hỗ trợ<input name="support_phone" required></label><label>Đơn vị tiền tệ<select name="currency"><option value="VND">VND</option></select></label><button class="primary full">Lưu cài đặt</button></form></section>`}
function staffPage(){let tab=state.staffTab||'list';let body=tab==='list'?`<div class="table-toolbar staff-toolbar"><input id="staffSearch" placeholder="⌕ Tìm tên, SĐT, mã nhân viên..."><select id="staffStatus"><option value="">Tất cả trạng thái</option><option value="active">Đang làm việc</option><option value="leave">Nghỉ phép</option><option value="terminated">Nghỉ việc</option></select></div><div class="staff-table-wrap"><table class="data-table staff-table"><thead><tr><th>Mã NV</th><th>Họ và tên</th><th>Vị trí</th><th>Phòng ban</th><th>Chi nhánh</th><th>SĐT</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="staffRows"><tr><td colspan="8">Đang tải dữ liệu...</td></tr></tbody></table></div>`:tab==='shifts'?`<div class="module-actions staff-actions"><button class="primary" onclick="openShiftForm()">+ Phân ca</button><button class="secondary" onclick="loadStaffShifts()">↻ Làm mới</button></div><div id="shiftRows" class="staff-list">Đang tải ca làm...</div>`:tab==='attendance'?`<div class="module-actions staff-actions"><button class="secondary" onclick="loadStaffAttendance()">↻ Làm mới</button></div><div id="staffAttendanceRows" class="staff-list">Đang tải chấm công...</div>`:`<div class="module-actions staff-actions"><button class="primary" onclick="openRoleForm()">+ Thêm vai trò</button></div><div id="roleRows" class="staff-list">Đang tải vai trò...</div>`;return `<div class="page-title"><div><h2>Nhân sự & phân quyền</h2><p class="hint">Hồ sơ nhân viên, ca làm, chấm công ảnh + GPS và quyền truy cập theo chi nhánh.</p></div>${tab==='list'?'<button class="primary" onclick="openStaffForm()">+ Thêm nhân sự</button>':''}</div><section class="card staff-shell"><div class="tabs staff-tabs"><button class="${tab==='list'?'active':''}" onclick="setStaffTab('list')">Danh sách nhân sự</button><button class="${tab==='shifts'?'active':''}" onclick="setStaffTab('shifts')">Phân ca</button><button class="${tab==='attendance'?'active':''}" onclick="setStaffTab('attendance')">Chấm công</button><button class="${tab==='roles'?'active':''}" onclick="setStaffTab('roles')">Phân quyền</button></div>${body}</section>`}
function setStaffTab(tab){state.staffTab=tab;renderPage();if(tab==='shifts')loadStaffShifts();if(tab==='attendance')loadStaffAttendance();if(tab==='roles')loadRoles()}
async function loadStaff(){try{let data=(await api('staff')).data;window.staffCache=data;let body=$('#staffRows');if(!body)return;let render=()=>{let q=($('#staffSearch')?.value||'').toLowerCase(),status=$('#staffStatus')?.value||'';let filtered=data.filter(x=>(`${x.employee_code} ${x.full_name} ${x.phone}`.toLowerCase().includes(q))&&(!status||x.employment_status===status));body.innerHTML=filtered.map(x=>`<tr><td>${x.employee_code}</td><td><span class="row-user"><span class="student-photo">👤</span><b>${x.full_name}</b></span></td><td>${x.position_title||'—'}</td><td>${x.department||'—'}</td><td>${x.branch_names||'—'}</td><td>${x.phone}</td><td><span class="status ${x.employment_status==='active'?'':'absent'}">${x.employment_status==='active'?'Đang làm việc':x.employment_status==='leave'?'Nghỉ phép':'Nghỉ việc'}</span></td><td><button class="icon-btn" title="Xem hồ sơ" onclick="staffDetail(${x.id})">◉</button><button class="icon-btn" title="Chỉnh sửa" onclick="openStaffForm(${x.id})">✎</button></td></tr>`).join('')||'<tr><td colspan="8">Không có nhân sự phù hợp</td></tr>'};render();$('#staffSearch').oninput=render;$('#staffStatus').onchange=render}catch(e){let b=$('#staffRows');if(b)b.innerHTML=`<tr><td colspan="8">${e.message}</td></tr>`}}
async function staffDetail(id){try{let d=(await api('staff/'+id)).data,s=d.staff;modal('Hồ sơ nhân sự',`<div class="staff-profile"><div class="portrait">👩🏻</div><div><h2>${s.full_name}</h2><p>${s.employee_code} · ${s.position_title||'Chưa có vị trí'}</p><span class="status ${s.employment_status==='active'?'':'absent'}">${s.employment_status==='active'?'Đang làm việc':s.employment_status}</span></div></div><div class="detail-grid staff-detail-grid"><div><p><b>Phòng ban:</b> ${s.department||'—'}</p><p><b>SĐT:</b> ${s.phone}</p><p><b>Email:</b> ${s.email||'—'}</p><p><b>Ngày vào làm:</b> ${s.hire_date||'—'}</p></div><div><p><b>Chi nhánh:</b> ${d.branches.map(x=>x.name).join(', ')||'—'}</p><p><b>Vai trò:</b> ${d.roles.map(x=>x.name).join(', ')||'Chưa cấp tài khoản'}</p><p><b>Tài khoản:</b> ${s.username||'Chưa kích hoạt'}</p><p><b>Lịch sử chấm công:</b> ${d.attendance.length} lượt</p></div></div><div class="module-actions"><button class="primary" onclick="closeModal();openStaffForm(${s.id})">Chỉnh sửa hồ sơ</button>${s.user_id?'<button class="secondary" onclick="toast(\'Tài khoản đang được quản lý theo vai trò được cấp\')">Quyền truy cập</button>':''}</div>`)}catch(e){toast(e.message)}}
async function openStaffForm(id){try{let existing=(window.staffCache||[]).find(x=>x.id===id)||{},branches=(await api('branches')).data,roles=(await api('roles')).data;modal(id?'Cập nhật nhân sự':'Thêm nhân sự',`<form id="staffForm" class="form-card staff-form"><div class="form-steps"><span class="active">1. Hồ sơ</span><span>2. Phân công</span><span>3. Tài khoản</span></div><fieldset data-step="1"><label>Mã nhân viên<input name="employee_code" value="${existing.employee_code||''}" ${id?'readonly':''} required></label><label>Họ và tên<input name="full_name" value="${existing.full_name||''}" required></label><label>Số điện thoại<input name="phone" value="${existing.phone||''}" required></label><label>Email<input name="email" type="email" value="${existing.email||''}"></label><label>Ngày vào làm<input name="hire_date" type="date" value="${existing.hire_date||new Date().toISOString().slice(0,10)}" required></label></fieldset><fieldset data-step="2" hidden><label>Phòng ban<input name="department" value="${existing.department||''}"></label><label>Vị trí<input name="position_title" value="${existing.position_title||''}"></label><label>Chi nhánh làm việc<div class="choice-grid">${branches.map(b=>`<label><input type="checkbox" name="branch_ids" value="${b.id}" ${existing.branch_names?.includes(b.name)?'checked':''}> ${b.name}</label>`).join('')}</div></label><label>Trạng thái<select name="employment_status"><option value="active" ${existing.employment_status!=='leave'&&existing.employment_status!=='terminated'?'selected':''}>Đang làm việc</option><option value="leave" ${existing.employment_status==='leave'?'selected':''}>Nghỉ phép</option><option value="terminated" ${existing.employment_status==='terminated'?'selected':''}>Nghỉ việc / khóa tài khoản</option></select></label></fieldset><fieldset data-step="3" hidden><p class="hint">Tạo tài khoản là tùy chọn. Nhân viên nghỉ việc sẽ bị khóa tài khoản nhưng lịch sử vẫn được giữ lại.</p>${id?'':`<label>Tên đăng nhập<input name="username" autocomplete="off"></label><label>Mật khẩu<input name="password" type="password" autocomplete="new-password"></label>`}<label>Vai trò<div class="choice-grid">${roles.filter(r=>r.code!=='admin'||state.role==='admin').map(r=>`<label><input type="checkbox" name="role_codes" value="${r.code}" ${existing.role_names?.includes(r.name)?'checked':''}> ${r.name}</label>`).join('')}</div></label></fieldset><div class="form-nav"><button type="button" class="secondary" id="staffBack" hidden>← Quay lại</button><button type="button" class="primary" id="staffNext">Tiếp theo →</button><button type="submit" class="primary" id="staffSave" hidden>${id?'Lưu thay đổi':'Tạo nhân sự'}</button></div></form>`);let form=$('#staffForm'),step=1,show=()=>{form.querySelectorAll('fieldset').forEach(x=>x.hidden=+x.dataset.step!==step);form.querySelectorAll('.form-steps span').forEach((x,i)=>x.classList.toggle('active',i<step));$('#staffBack').hidden=step===1;$('#staffNext').hidden=step===3;$('#staffSave').hidden=step!==3};$('#staffNext').onclick=()=>{if(step===1&&!form.reportValidity())return;step++;show()};$('#staffBack').onclick=()=>{step--;show()};form.onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(form));f.branch_ids=[...form.querySelectorAll('[name=branch_ids]:checked')].map(x=>+x.value);f.role_codes=[...form.querySelectorAll('[name=role_codes]:checked')].map(x=>x.value);if(!f.branch_ids.length)throw new Error('Chọn ít nhất một chi nhánh làm việc');if(!id&&f.username){f.account={username:f.username,password:f.password};delete f.username;delete f.password}await api(id?'staff/'+id:'staff',{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadStaff();toast(id?'Đã cập nhật nhân sự':'Đã tạo hồ sơ nhân sự và phân quyền')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
async function loadStaffShifts(){try{let data=(await api('staff/shifts')).data,box=$('#shiftRows');if(!box)return;box.innerHTML=data.map(x=>`<article class="staff-item"><b>${x.full_name}</b><span>${x.branch_name}</span><span>${new Date(x.starts_at).toLocaleString('vi-VN')} — ${new Date(x.ends_at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</span><span class="status">${x.shift_status==='scheduled'?'Đã phân ca':x.shift_status}</span></article>`).join('')||'<div class="empty">Chưa có ca làm</div>'}catch(e){toast(e.message)}}
async function openShiftForm(){try{let staff=(window.staffCache||[]);if(!staff.length){await loadStaff();staff=window.staffCache||[]}let branches=(await api('branches')).data;modal('Phân ca làm việc',`<form id="shiftForm" class="form-card"><label>Nhân viên<select name="staff_id">${staff.filter(x=>x.employment_status==='active').map(x=>`<option value="${x.id}">${x.employee_code} — ${x.full_name}</option>`).join('')}</select></label><label>Chi nhánh<select name="branch_id">${branches.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label>Bắt đầu<input name="starts_at" type="datetime-local" required></label><label>Kết thúc<input name="ends_at" type="datetime-local" required></label><label>Ghi chú<input name="note"></label><button class="primary full">Lưu phân ca</button></form>`);$('#shiftForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.staff_id=+f.staff_id;f.branch_id=+f.branch_id;await api('staff/shifts',{method:'POST',body:JSON.stringify(f)});closeModal();loadStaffShifts();toast('Đã phân ca làm việc')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
async function loadStaffAttendance(){try{let data=(await api('staff/attendance')).data,box=$('#staffAttendanceRows');if(!box)return;box.innerHTML=data.map(x=>`<article class="staff-item"><b>${x.full_name}</b><span>${x.check_type==='check_in'?'Check-in':'Check-out'} · ${new Date(x.checked_at).toLocaleString('vi-VN')}</span><span>${x.latitude?.toFixed?.(4)||'—'}, ${x.longitude?.toFixed?.(4)||'—'}</span><span class="status ${x.verification_status==='verified'?'':'wait'}">${x.verification_status==='verified'?'Đã xác minh':'Chờ xác minh'}</span></article>`).join('')||'<div class="empty">Chưa có dữ liệu chấm công</div>'}catch(e){toast(e.message)}}
async function loadRoles(){try{let data=(await api('roles')).data,box=$('#roleRows');if(!box)return;window.roleCache=data;box.innerHTML=data.map(x=>`<article class="staff-item"><b>${x.name}</b><span>${x.description||'—'} · Phạm vi: ${x.scope_type==='chain'?'Toàn chuỗi':x.scope_type==='self'?'Cá nhân':'Chi nhánh'}</span><span>${x.user_count} người dùng</span><button class="icon-btn" onclick="openRoleForm(${x.id})" title="Thiết lập quyền">✎</button></article>`).join('')}catch(e){toast(e.message)}}
async function openRoleForm(id){try{let role=(window.roleCache||[]).find(x=>x.id===id)||{},permissions=(await api('permissions')).data;modal(id?'Thiết lập quyền: '+role.name:'Thêm vai trò',`<form id="roleForm" class="form-card"><label>Tên vai trò<input name="name" value="${role.name||''}" required></label>${id?'':`<label>Mã vai trò<input name="code" required pattern="[a-z0-9_]+"></label>`}<label>Mô tả<input name="description" value="${role.description||''}"></label><label>Phạm vi<select name="scope_type"><option value="branch" ${role.scope_type!=='chain'&&role.scope_type!=='self'?'selected':''}>Chi nhánh</option><option value="chain" ${role.scope_type==='chain'?'selected':''}>Toàn chuỗi</option><option value="self" ${role.scope_type==='self'?'selected':''}>Dữ liệu cá nhân</option></select></label>${id?`<fieldset class="permission-list"><legend>Quyền chức năng</legend>${permissions.map(p=>`<label><input type="checkbox" name="permission_ids" value="${p.id}" ${p.role_ids.split(',').includes(String(id))?'checked':''}> <b>${p.module_key}</b> — ${p.description}</label>`).join('')}</fieldset>`:''}<button class="primary full">${id?'Lưu quyền':'Tạo vai trò'}</button></form>`);$('#roleForm').onsubmit=async e=>{e.preventDefault();try{let form=e.target,f=Object.fromEntries(new FormData(form));if(id)f.permission_ids=[...form.querySelectorAll('[name=permission_ids]:checked')].map(x=>+x.value);await api(id?'roles/'+id:'roles',{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadRoles();toast('Đã lưu vai trò và quyền')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
function genericPage(v){let title={branches:'Quản lý chi nhánh',leads:'Tư vấn & Lead',aftercare:'Chăm sóc sau điều trị',messages:'Tin nhắn khách hàng',rooms:'Phòng dịch vụ',schedule:'Lịch học',results:'Kết quả học tập',tuition:'Học phí & thanh toán',materials:'Tài liệu học tập',profile:'Hồ sơ cá nhân'}[v]||'SpaFlow';let canWrite=state.role!=='student';return pageWrap(title,canWrite?'+ Thêm mới':'',`<div class="table-toolbar"><input id="moduleSearch" placeholder="⌕ Tìm kiếm ${title.toLowerCase()}..."><select id="moduleStatus"><option value="">Tất cả trạng thái</option><option value="active">Đang hoạt động</option><option value="inactive">Tạm dừng</option></select></div><table class="data-table"><thead><tr><th>Tên</th><th>Nội dung</th><th>Trạng thái</th><th>Cập nhật</th><th>Thao tác</th></tr></thead><tbody id="moduleRows"><tr><td colspan="5">Đang tải dữ liệu...</td></tr></tbody></table>`,canWrite?`openModuleForm('${v}','${title}')`:null)}function pageWrap(title,action,body,handler){return `<div class="page-title"><h2>${title}</h2>${action?`<button class="primary" onclick="${handler||`toast('Chức năng ${action.replace('+ ','')} đang được triển khai')`}">${action}</button>`:''}</div><section class="card table-card">${body}</section>`}
function modal(title,body){let root=$('#modalRoot');root._returnFocus=document.activeElement;root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle">${title}</h2><button class="close" type="button" aria-label="Đóng cửa sổ" title="Đóng" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>root.querySelector('.modal input, .modal select, .modal textarea, .modal button')?.focus(),0)}function closeModal(){let root=$('#modalRoot'),returnFocus=root._returnFocus;root.innerHTML='';stopCamera();returnFocus?.focus?.()}
function classDetail(id){let c=state.classes.find(x=>x.id===id);modal('♢ Lớp học: '+c.name,`<div class="class-info"><span style="font-size:35px">♢</span><div><h3>${c.name}</h3><p>${c.id} · ${c.branch} · Giảng viên: ${c.teacher} · ${c.schedule}</p></div><span class="status" style="margin-left:auto">${c.status}</span></div><div class="tabs"><button class="active">Danh sách học viên (${state.students.length})</button><button onclick="toast('Tab lịch học')">Lịch học</button><button onclick="openAttendance()">Điểm danh</button><button onclick="toast('Tab bài tập')">Bài tập</button><button onclick="toast('Tab kết quả')">Kết quả</button></div>${studentTable()}`)}
function studentDetail(id){let s=state.students.find(x=>x.id===id);modal('♙ Hồ sơ học viên',`<div class="detail-grid"><aside class="profile-card"><div class="portrait">👩🏻</div><h2>${s.name}</h2><span class="status">${s.status}</span><p>☎ ${s.phone}</p><p>✉ ${s.name.toLowerCase().replaceAll(' ','')}@gmail.com</p><p>⌂ SpaFlow Quận 1</p><button class="primary full" onclick="openAttendance()">⌖ Điểm danh buổi học</button></aside><div><div class="tabs"><button class="active">Thông tin</button><button class="active">Lịch sử điểm danh</button><button onclick="toast('Kết quả học tập: 8.8/10')">Kết quả</button><button onclick="toast('Học phí còn lại: 4.500.000 đ')">Học phí</button></div><div class="attendance-summary"><div class="summary-box">Tổng buổi<b>12</b></div><div class="summary-box">Đã tham gia<b>${s.attendance.split('/')[0]}</b></div><div class="summary-box">Tỷ lệ<b>${s.rate}</b></div></div><h3>Lịch sử điểm danh</h3>${attendanceTable()}</div></div>`)}
let stream;function openAttendance(){modal('⌖ Điểm danh buổi học',`<div class="checkin"><div class="camera" id="camera"><div class="camera-tip">📷<br><br>Nhấn “Bật camera” để chụp ảnh check-in</div></div><div class="form-card"><h3>Thông tin check-in</h3><div class="check-row"><b>Lớp:</b> Chăm sóc da chuyên sâu K12</div><div class="check-row"><b>Buổi học:</b> Buổi 12 — Thực hành chăm sóc da</div><div class="check-row"><b>Thời gian:</b> 08:30 – 11:30</div><div class="check-row" id="gpsState"><b>Vị trí GPS:</b> Chưa lấy vị trí</div><div class="notice">Dữ liệu ảnh và vị trí chỉ được dùng cho điểm danh, theo chính sách lưu giữ của SpaFlow.</div><button class="manual" onclick="startCamera()">📷 Bật camera</button><button class="manual" onclick="getGPS()">⌖ Lấy vị trí GPS</button><button class="primary full" onclick="confirmAttendance()">✓ Xác nhận điểm danh</button><button class="manual" onclick="toast('Yêu cầu xác minh thủ công đã gửi')">Gửi yêu cầu xác minh thủ công</button></div></div>`)}
async function startCamera(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'}});let v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.srcObject=stream;$('#camera').replaceChildren(v);toast('Camera đã sẵn sàng. Ảnh sẽ được chụp khi xác nhận.')}catch(e){toast('Không thể mở camera. Bạn có thể gửi yêu cầu xác minh thủ công.')}}function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null}function getGPS(){if(!navigator.geolocation)return toast('Trình duyệt không hỗ trợ GPS');navigator.geolocation.getCurrentPosition(p=>{$('#gpsState').innerHTML='<b>Vị trí GPS:</b> Đã xác minh (±'+Math.round(p.coords.accuracy)+'m)';$('#gpsState').dataset.gps=`${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)}`;toast('Đã lấy vị trí GPS')},()=>toast('Không lấy được vị trí. Hãy cấp quyền hoặc xác minh thủ công.'),{enableHighAccuracy:true,timeout:10000})}function confirmAttendance(){let v=$('#camera video'),image='';if(v){let c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);image=c.toDataURL('image/jpeg',.72)}let gps=$('#gpsState').dataset.gps||'Chờ xác minh';state.attendance.unshift({date:new Date().toLocaleDateString('vi-VN'),time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}),status:gps==='Chờ xác minh'?'Chờ xác minh':'Có mặt',gps,image});localStorage.setItem('spaflow-attendance',JSON.stringify(state.attendance));closeModal();toast(gps==='Chờ xác minh'?'Đã gửi yêu cầu xác minh thủ công':'Điểm danh thành công!');renderPage()}
function rolePicker(){modal('Chọn vai trò demo',`<div class="role-menu">${Object.entries(roles).map(([k,r])=>`<button class="role-choice" onclick="switchRole('${k}')"><b>${r.name}</b><br><small>${r.caption}</small></button>`).join('')}</div>`)}function switchRole(role){state.role=role;localStorage.setItem('spaflow-role',role);state.view='dashboard';closeModal();renderShell();renderPage();toast('Đã chuyển sang vai trò '+roles[role].name)}function branchPicker(){modal('Chọn chi nhánh',`<div class="role-menu">${['SpaFlow Quận 1','SpaFlow Quận 7','SpaFlow Thủ Đức','Toàn hệ thống (3 chi nhánh)'].map(b=>`<button class="role-choice" onclick="switchBranch('${b}')">⌂ <b>${b}</b></button>`).join('')}</div>`)}function switchBranch(b){state.branch=b;localStorage.setItem('spaflow-branch',b);closeModal();renderShell();renderPage();toast('Đã chuyển '+b)}function guide(){modal('Hướng dẫn sử dụng SpaFlow',`<ol class="guide-list"><li>Chọn chi nhánh trên thanh đầu trang để giới hạn dữ liệu.</li><li>Đổi vai trò bằng thẻ tài khoản ở sidebar để xem quyền từng người dùng.</li><li>Vào <b>Đào tạo → Lớp học</b>, mở lớp và chọn học viên để xem luồng popup 3 cấp.</li><li>Học viên chọn <b>Điểm danh</b>, cấp quyền camera/GPS rồi xác nhận.</li><li>Dùng thanh tìm kiếm để mở nhanh danh sách khách hàng.</li></ol>`)}function quickAction(a){if(a.includes('lịch')){state.view='appointments'}else if(a.includes('khách'))state.view='customers';else if(a.includes('lớp'))state.view='classes';else state.view='attendance';renderShell();renderPage()}function setView(v){state.view=v;renderShell();renderPage()}function openClasses(){state.view='classes';renderShell();renderPage()}function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3000)}
async function loadDashboard(){try{let d=(await api('dashboard')).data;document.querySelectorAll('[data-kpi]').forEach(e=>{let k=e.dataset.kpi;if(d[k]!==undefined)e.textContent=k==='revenue'?money(d[k]):new Intl.NumberFormat('vi-VN').format(d[k])})}catch(e){toast(e.message)}}
async function loadCustomers(q=''){try{let d=(await api('customers?q='+encodeURIComponent(q))).data;window.customerCache=d;let body=$('#customerRows');if(!body)return;body.innerHTML=d.map(c=>`<tr><td>${c.code}</td><td class="row-user"><span class="student-photo">👩🏻</span><b>${c.full_name}</b></td><td>${c.phone}</td><td>${c.customer_group}</td><td><span class="status">${c.status}</span></td><td><button class="icon-btn" onclick="openCustomerForm(${c.id})">✎</button></td></tr>`).join('')||'<tr><td colspan="6">Không có dữ liệu phù hợp</td></tr>';let input=$('#customerSearch');if(input)input.oninput=e=>loadCustomers(e.target.value)}catch(e){let body=$('#customerRows');if(body)body.innerHTML='<tr><td colspan="6">'+e.message+'</td></tr>'}}
async function loadServices(){try{let data=(await api('services')).data;window.serviceCache=data;let body=$('#serviceRows');if(!body)return;let render=()=>{let q=($('#serviceSearch')?.value||'').toLowerCase(),st=$('#serviceState')?.value||'';let rows=data.filter(s=>s.name.toLowerCase().includes(q)&&(st===''||String(s.active)===st));body.innerHTML=rows.map(s=>`<tr><td><b>${s.name}</b></td><td>${s.duration_min} phút</td><td>${money(s.price)}</td><td><span class="status ${s.active?'':'absent'}">${s.active?'Đang dùng':'Tạm dừng'}</span></td><td><button class="icon-btn" onclick="openServiceForm(${s.id})">✎</button></td></tr>`).join('')||'<tr><td colspan="5">Không có dịch vụ phù hợp</td></tr>'};render();$('#serviceSearch').oninput=render;$('#serviceState').onchange=render}catch(e){$('#serviceRows').innerHTML='<tr><td colspan="5">'+e.message+'</td></tr>'}}
async function loadProducts(){try{let data=(await api('products')).data;window.productCache=data;let body=$('#productRows');if(!body)return;body.innerHTML=data.map(p=>`<tr><td>${p.sku}</td><td><b>${p.name}</b></td><td class="${p.stock<=p.reorder_level?'low-stock':''}">${p.stock}</td><td>${p.reorder_level}</td><td>${money(p.price)}</td><td><button class="icon-btn" onclick="openProductForm(${p.id})">✎</button></td></tr>`).join('')||'<tr><td colspan="6">Chưa có sản phẩm</td></tr>'}catch(e){$('#productRows').innerHTML='<tr><td colspan="6">'+e.message+'</td></tr>'}}
async function loadInvoices(){try{let data=(await api('invoices')).data;window.invoiceCache=data;let body=$('#invoiceRows');if(!body)return;let render=()=>{let q=($('#invoiceSearch')?.value||'').toLowerCase(),st=$('#invoiceState')?.value||'';let rows=data.filter(i=>(i.code+' '+(i.customer_name||'')).toLowerCase().includes(q)&&(!st||i.status===st));body.innerHTML=rows.map(i=>{let remaining=i.total-i.paid;return `<tr><td><b>${i.code}</b></td><td>${i.customer_name||'Khách lẻ'}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td class="${remaining>0?'low-stock':''}">${money(remaining)}</td><td><span class="status ${i.status==='paid'?'':'wait'}">${i.status==='paid'?'Đã thanh toán':i.status==='partial'?'Còn công nợ':'Chưa thanh toán'}</span></td><td>${remaining>0?`<button class="icon-btn" onclick="openPaymentForm(${i.id})">◴ Thu tiền</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="7">Không có hóa đơn phù hợp</td></tr>'};render();$('#invoiceSearch').oninput=render;$('#invoiceState').onchange=render}catch(e){$('#invoiceRows').innerHTML='<tr><td colspan="7">'+e.message+'</td></tr>'}}
function openPaymentForm(id){let i=(window.invoiceCache||[]).find(x=>x.id===id);if(!i)return toast('Không tìm thấy hóa đơn');let remaining=i.total-i.paid;modal('Thu tiền hóa đơn '+i.code,`<form id="paymentForm" class="form-card"><p>Khách hàng: <b>${i.customer_name||'Khách lẻ'}</b></p><p>Công nợ còn lại: <b class="low-stock">${money(remaining)}</b></p><label>Số tiền thu<input name="amount" type="number" min="1" max="${remaining}" step="1000" value="${remaining}" required></label><label>Phương thức<select name="method"><option value="cash">Tiền mặt</option><option value="transfer">Chuyển khoản</option><option value="card">Thẻ</option></select></label><button class="primary full">Xác nhận thanh toán</button></form>`);$('#paymentForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.invoice_id=id;f.amount=Number(f.amount);await api('payments',{method:'POST',body:JSON.stringify(f)});closeModal();loadInvoices();toast('Đã ghi nhận thanh toán')}catch(err){toast(err.message)}}}
async function loadReports(){try{let d=(await api('reports/overview')).data;let box=$('#reportRows');if(!box)return;box.innerHTML=`<article class="metric"><span>Doanh thu hóa đơn</span><b>${money(d.revenue)}</b></article><article class="metric"><span>Đã thanh toán</span><b>${money(d.paid)}</b></article><article class="metric"><span>Công nợ còn lại</span><b>${money(d.debt)}</b></article>`;$('#lowStockRows').innerHTML=d.low_stock.length?`<table class="branch-table">${d.low_stock.map(x=>`<tr><td>${x.name}</td><td class="low-stock">Còn ${x.stock} / ngưỡng ${x.reorder_level}</td></tr>`).join('')}</table>`:'Không có sản phẩm dưới ngưỡng cảnh báo'}catch(e){toast(e.message)}}
async function loadSettings(){try{let data=(await api('settings')).data;let s=Object.fromEntries(data.map(x=>[x.setting_key,x.setting_value]));let f=$('#settingsForm');if(!f)return;for(let k of ['spa_name','support_phone','currency'])if(f.elements[k])f.elements[k].value=s[k]||'';f.onsubmit=async e=>{e.preventDefault();try{let values=Object.fromEntries(new FormData(f));await api('settings',{method:'POST',body:JSON.stringify({settings:values})});toast('Đã lưu cài đặt hệ thống')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
function openServiceForm(id){let s=(window.serviceCache||[]).find(x=>x.id===id)||{};modal(id?'Cập nhật dịch vụ':'Thêm dịch vụ',`<form id="serviceForm" class="form-card"><label>Tên dịch vụ<input name="name" value="${s.name||''}" required></label><label>Thời lượng (phút)<input name="duration_min" type="number" min="1" value="${s.duration_min||60}" required></label><label>Giá bán<input name="price" type="number" min="0" step="1000" value="${s.price||0}" required></label><label>Trạng thái<select name="active"><option value="1" ${s.active!==0?'selected':''}>Đang dùng</option><option value="0" ${s.active===0?'selected':''}>Tạm dừng</option></select></label><button class="primary full">${id?'Lưu thay đổi':'Tạo dịch vụ'}</button></form>`);$('#serviceForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.duration_min=Number(f.duration_min);f.price=Number(f.price);f.active=Number(f.active);await api(id?'services/'+id:'services',{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadServices();toast('Đã lưu dịch vụ')}catch(err){toast(err.message)}}}
function openProductForm(id){let p=(window.productCache||[]).find(x=>x.id===id)||{};modal(id?'Cập nhật sản phẩm':'Thêm sản phẩm',`<form id="productForm" class="form-card"><label>Mã SKU<input name="sku" value="${p.sku||''}" ${id?'readonly':''} required></label><label>Tên sản phẩm<input name="name" value="${p.name||''}" required></label><label>Giá bán<input name="price" type="number" min="0" step="1000" value="${p.price||0}" required></label><label>Ngưỡng cảnh báo<input name="reorder_level" type="number" min="0" value="${p.reorder_level||5}" required></label>${id?'':`<label>Tồn đầu kỳ<input name="stock" type="number" min="0" value="0" required></label>`}<button class="primary full">${id?'Lưu thay đổi':'Tạo sản phẩm'}</button></form>`);$('#productForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));for(let k of ['price','reorder_level','stock'])if(k in f)f[k]=Number(f[k]);await api(id?'products/'+id:'products',{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadProducts();toast('Đã lưu sản phẩm')}catch(err){toast(err.message)}}}
function openStockForm(){let options=(window.productCache||[]).map(p=>`<option value="${p.id}">${p.name} (tồn: ${p.stock})</option>`).join('');modal('Nhập / xuất kho',`<form id="stockForm" class="form-card"><label>Sản phẩm<select name="product_id">${options}</select></label><label>Loại giao dịch<select name="movement_type"><option value="in">Nhập kho</option><option value="out">Xuất kho</option><option value="adjustment">Điều chỉnh (+/-)</option></select></label><label>Số lượng<input name="quantity" type="number" required></label><label>Ghi chú<input name="note"></label><button class="primary full">Xác nhận cập nhật kho</button></form>`);$('#stockForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.product_id=Number(f.product_id);f.quantity=Number(f.quantity);await api('stock-movements',{method:'POST',body:JSON.stringify(f)});closeModal();loadProducts();toast('Đã cập nhật tồn kho')}catch(err){toast(err.message)}}}
async function loadModuleRecords(key){try{let data=(await api('modules/'+key)).data;window.moduleCache=data;let body=$('#moduleRows');if(!body)return;let render=()=>{let q=($('#moduleSearch')?.value||'').toLowerCase(),st=$('#moduleStatus')?.value||'';let rows=data.filter(x=>((x.title+' '+x.details).toLowerCase().includes(q))&&(!st||x.status===st));body.innerHTML=rows.map(x=>`<tr><td><b>${x.title}</b></td><td>${x.details||'—'}</td><td><span class="status ${x.status==='active'?'':'absent'}">${x.status==='active'?'Đang hoạt động':'Tạm dừng'}</span></td><td>${new Date(x.updated_at).toLocaleDateString('vi-VN')}</td><td>${state.role==='student'?'—':`<button class="icon-btn" onclick="openModuleForm('${key}','',${x.id})">✎</button><button class="icon-btn" onclick="deleteModuleRecord('${key}',${x.id})">×</button>`}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có dữ liệu</td></tr>'};render();$('#moduleSearch').oninput=render;$('#moduleStatus').onchange=render}catch(e){let body=$('#moduleRows');if(body)body.innerHTML='<tr><td colspan="5">'+e.message+'</td></tr>'}}
function openModuleForm(key,title,id){let x=(window.moduleCache||[]).find(i=>i.id===id)||{};modal(id?'Cập nhật '+(title||'bản ghi'):'Thêm '+(title||'bản ghi'),`<form id="moduleForm" class="form-card"><label>Tên<input name="title" value="${x.title||''}" required></label><label>Nội dung / ghi chú<textarea name="details" rows="4">${x.details||''}</textarea></label><label>Trạng thái<select name="status"><option value="active" ${x.status!=='inactive'?'selected':''}>Đang hoạt động</option><option value="inactive" ${x.status==='inactive'?'selected':''}>Tạm dừng</option></select></label><button class="primary full">${id?'Lưu thay đổi':'Tạo mới'}</button></form>`);$('#moduleForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));await api(id?'modules/'+key+'/'+id:'modules/'+key,{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadModuleRecords(key);toast('Đã lưu dữ liệu')}catch(err){toast(err.message)}}}
async function deleteModuleRecord(key,id){if(!confirm('Xóa bản ghi này?'))return;try{await api('modules/'+key+'/'+id,{method:'DELETE'});loadModuleRecords(key);toast('Đã xóa bản ghi')}catch(e){toast(e.message)}}
async function loadAppointments(){try{let d=(await api('appointments')).data;let box=$('#appointmentRows');if(!box)return;box.innerHTML=d.slice(0,30).map(a=>`<div class="appointment"><span class="time">${new Date(a.starts_at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</span><span class="face">👩🏻</span><span><b>${a.customer_name}</b><small>${a.service_name||'Chưa chọn dịch vụ'} · ${a.staff_name||'Chưa phân công'}</small></span><span class="pill ${a.status==='cancelled'?'wait':''}">${a.status}</span><button class="icon-btn" type="button" title="Hủy lịch hẹn" aria-label="Hủy lịch hẹn của ${a.customer_name}" onclick="cancelAppointment(${a.id})">×</button></div>`).join('')||'<div class="empty">Chưa có lịch hẹn</div>'}catch(e){toast(e.message)}}
function openCustomerForm(id){let c=(window.customerCache||[]).find(x=>x.id===id)||{};modal(id?'Cập nhật khách hàng':'Thêm khách hàng',`<form id="customerForm" class="form-card"><label>Họ và tên<input name="full_name" value="${c.full_name||''}" required></label><label>Số điện thoại<input name="phone" value="${c.phone||''}" required></label><label>Nhóm khách<select name="customer_group"><option>${c.customer_group||'Tiềm năng'}</option><option>Khách thân thiết</option><option>Khách VIP</option></select></label><label>Trạng thái<select name="status"><option>${c.status||'Mới tư vấn'}</option><option>Đang điều trị</option><option>Đã đặt lịch</option></select></label><button class="primary full">${id?'Lưu thay đổi':'Tạo khách hàng'}</button></form>`);$('#customerForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));await api(id?'customers/'+id:'customers',{method:id?'PUT':'POST',body:JSON.stringify(f)});closeModal();loadCustomers();toast(id?'Đã cập nhật khách hàng':'Đã tạo khách hàng')}catch(err){toast(err.message)}}}
function openAppointmentForm(){let options=(window.customerCache||[]).map(c=>`<option value="${c.id}">${c.full_name} — ${c.phone}</option>`).join('')||'<option value="1">Khách hàng demo 01</option>';modal('Đặt lịch hẹn',`<form id="appointmentForm" class="form-card"><label>Khách hàng<select name="customer_id">${options}</select></label><label>Thời gian<input type="datetime-local" name="starts_at" required></label><label>Nhân viên<input name="staff_name" value="KTV Lan Hương"></label><label>Ghi chú<input name="note"></label><button class="primary full">Tạo lịch hẹn</button></form>`);$('#appointmentForm').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.customer_id=Number(f.customer_id);await api('appointments',{method:'POST',body:JSON.stringify(f)});closeModal();loadAppointments();toast('Đã tạo lịch hẹn')}catch(err){toast(err.message)}}}
async function cancelAppointment(id){if(!confirm('Hủy lịch hẹn này?'))return;try{await api('appointments/'+id,{method:'DELETE'});loadAppointments();toast('Đã hủy lịch hẹn')}catch(e){toast(e.message)}}
function loginDialog(){modal('Đăng nhập SpaFlow',`<form id="loginForm" class="form-card"><p>Chọn một tài khoản demo để kiểm thử phân quyền và dữ liệu chi nhánh.</p><label>Tài khoản<input name="username" value="admin" required></label><label>Mật khẩu<input name="password" value="admin" type="password" required></label><button class="primary full">Đăng nhập</button><p class="hint">admin/admin · cskh/cskh · manager.q1/manager · student.mai/student</p></form>`);$('#loginForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let x=await api('login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});apiToken=x.token;sessionStorage.setItem('spaflow-token',apiToken);state.role=x.user.role;state.branch=x.user.branch_name||'Toàn hệ thống (3 chi nhánh)';closeModal();renderShell();renderPage();toast('Đăng nhập thành công')}catch(err){toast(err.message)}}}
async function bootstrap(){init();if(!apiToken)return loginDialog();try{let x=await api('me');state.role=x.data.role;state.branch=x.data.branch_name||'Toàn hệ thống (3 chi nhánh)';renderShell();renderPage()}catch(e){apiToken='';sessionStorage.removeItem('spaflow-token');loginDialog()}}
Object.assign(window,{quickAction,setView,openClasses,openAttendance,classDetail,studentDetail,closeModal,startCamera,getGPS,confirmAttendance,switchRole,switchBranch,toast,openCustomerForm,openAppointmentForm,cancelAppointment,openServiceForm,openProductForm,openStockForm,openPaymentForm,openModuleForm,deleteModuleRecord,loadProducts,loadReports,setStaffTab,loadStaff,staffDetail,openStaffForm,loadStaffShifts,openShiftForm,loadStaffAttendance,loadRoles,openRoleForm});bootstrap();
